// ---------------------------------------------------------------------------
// Customer Order Line Item — composed from shared variant base fields
// ---------------------------------------------------------------------------

/**
 * Line item for a customer order — supports parts, labor, and bicycles.
 *
 * Uses shared variant definitions as the source of truth for field shapes,
 * composed into a flat object schema to maintain backward compatibility
 * with existing service layer code that accesses fields without narrowing.
 */
export const customerOrderLineItemSchema = z.object({
  lineType: z.enum(['part', 'labor', 'bicycle']),
  // Part-specific (from partLineItemVariant)
  partId: z.string().nullable().optional(),
  // Labor-specific (from laborLineItemVariant)
  laborServiceId: z.string().nullable().optional(),
  minutesWorked: z.number().int().positive().nullable().optional(),
  hourlyRateSnapshot: z.number().int().nonnegative().nullable().optional(),
  // Base fields (shared across all variants)
  description: partLineItemVariant.toSchema().shape.description,
  quantity: partLineItemVariant.toSchema().shape.quantity,
  unitPriceNet: partLineItemVariant.toSchema().shape.unitPriceNet,
  vatRateId: partLineItemVariant.toSchema().shape.vatRateId,
  discountPercent: partLineItemVariant.toSchema().shape.discountPercent,
  // Bicycle-specific (from bicycleLineItemVariant)
  bicycleId: z.string().nullable().optional(),
  bicycleBrand: z.string().max(100).nullable().optional(),
  bicycleModel: z.string().max(200).nullable().optional(),
  bicycleYear: z.number().int().min(1900).max(new Date().getFullYear() + 1).nullable().optional(),
  bicycleColor: z.string().max(50).nullable().optional(),
  bicycleFrameSize: z.string().max(20).nullable().optional(),
})

export type CustomerOrderLineItem = z.infer<typeof customerOrderLineItemSchema>

/** Input for creating a customer order with optional deposit */
export const createCustomerOrderInputSchema = z.object({
  customerId: z.string().min(1, 'customerId is required'),
  lineItems: z.array(customerOrderLineItemSchema).min(1, 'At least one line item is required'),
  depositAmount: z.number().int().nonnegative('depositAmount must be non-negative').nullable().optional(),
  paymentMethod: paymentMethodSchema.nullable().optional(),
  expectedDeliveryDate: z.string().datetime().nullable().optional(),
  internalNotes: z.string().max(2000).nullable().optional(),
}).refine(
  (data) => {
    // If depositAmount > 0, paymentMethod must be provided
    if ((data.depositAmount ?? 0) > 0 && !data.paymentMethod) {
      return false
    }
    return true
  },
  { message: 'paymentMethod is required when depositAmount > 0', path: ['paymentMethod'] }
)

export type CreateCustomerOrderInput = z.infer<typeof createCustomerOrderInputSchema>

/** Customer order status */
export const customerOrderStatusSchema = z.enum(['pending', 'ordered', 'ready', 'fulfilled', 'cancelled'])
export type CustomerOrderStatus = z.infer<typeof customerOrderStatusSchema>

